/* EditalOS — agenda de execução com planos produzidos no NotebookLM. Sem IA embutida. */
const state={
  data:null,page:'calendar',calendarDay:null,notebookPrompt:'',notebookPreview:null,
  notebookFileName:'',notebookMode:'append',modal:null,contentExamId:null
};
let focusInterval=null;let focusSeconds=0;
const $=(s,root=document)=>root.querySelector(s);
const esc=x=>String(x==null?'':x).replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const isoDay=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const toDate=s=>new Date(`${s||state.data?.today||isoDay(new Date())}T12:00:00`);
const fmtLong=s=>s?toDate(s).toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',year:'numeric'}):'Data não informada';
const fmtDay=s=>s?toDate(s).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}):'—';
const num=n=>Number(n||0).toLocaleString('pt-BR',{maximumFractionDigits:1});
const subjectName=id=>state.data?.subjects?.find(x=>x.id===id)?.name||id||'Matéria';
const activityLabel=t=>({teoria:'Teoria',questoes:'Questões',revisao:'Revisão',simulado:'Simulado',lei_seca:'Lei seca',resumo:'Resumo',redacao:'Redação',outro:'Atividade'})[t]||'Estudo';
const eventLabel=t=>({inscricao:'Inscrição',isencao:'Isenção',prova:'Prova',pagamento:'Pagamento',recurso:'Recurso',resultado:'Resultado',convocacao:'Convocação',taf:'TAF'})[t]||'Prazo';
const navItems=[['dashboard','Visão geral','dashboard'],['calendar','Minha agenda','calendar'],['notebooklm','Planejamento NotebookLM','notebook'],['exams','Concursos','exams'],['content','Cobertura do edital','content'],['errors','Caderno de erros','errors'],['qconcursos','QConcursos','qconcursos'],['settings','Preferências','settings']];
const icons={
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',
 notebook:'<path d="M5 3h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5zM8 3v18M12 8h5M12 12h5M12 16h3"/>',
 exams:'<path d="M4 4h16v17H4zM8 4V2h8v2M8 9h8M8 13h8M8 17h5"/>',
 content:'<path d="M4 4h16v17H4zM8 8h8M8 12h8M8 16h5"/>',
 qconcursos:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5.2 2c-1.1 1.1-2.2 1.3-2.2 3M12 17h.01"/>',
	settings:'<circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.1-1l2-1.5-2-3.5-2.4 1a8 8 0 0 0-1.7-1L14.5 3h-4l-.3 3a8 8 0 0 0-1.7 1l-2.4-1-2 3.5L6 11a8 8 0 0 0 0 2l-2 1.5 2 3.5 2.4-1a8 8 0 0 0 1.7 1l.4 3h4l.4-3a8 8 0 0 0 1.7-1l2.4 1 2-3.5L19 13a8 8 0 0 0 0-1z"/>'
,
 dashboard:'<path d="M4 13h6V4H4zM14 20h6v-9h-6zM4 20h6v-3H4zM14 8h6V4h-6z"/>',
 errors:'<path d="M12 3 2 21h20L12 3zM12 9v5M12 18h.01"/>'
};
const svg=k=>`<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.calendar}</svg>`;
async function api(path,options={}){const r=await fetch(path,options);let body;try{body=await r.json()}catch{body={detail:'Resposta inesperada do servidor'}}if(!r.ok){let m=body.detail||`Erro HTTP ${r.status}`;throw new Error(typeof m==='string'?m:JSON.stringify(m))}return body}
const post=(url,data)=>api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
const patch=(url,data)=>api(url,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
function toast(message,error=false){const root=$('#toast-root');const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;root.append(el);setTimeout(()=>el.remove(),5000)}
async function refresh(){try{state.data=await api('/api/bootstrap');if(!state.calendarDay)state.calendarDay=state.data.today;render()}catch(e){toast(e.message,true);$('#page').innerHTML=`<div class="notice notice-error">Não foi possível carregar o EditalOS: ${esc(e.message)}</div>`}}
function go(page){state.page=page;$('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})}
async function loadStorageStatus(){try{const r=await fetch('/api/storage/status');const x=await r.json();const el=$('#storageStatusText');if(!el)return;const c=x.counts||{};el.textContent=x.ephemeral_environment?'Atenção: este ambiente é temporário; configure EDITALOS_DATA ou um banco externo.':`Banco persistente ativo · ${c.sessions||0} sessões · último salvamento ${x.last_saved||'agora'}`;}catch(e){const el=$('#storageStatusText');if(el)el.textContent='Não foi possível verificar o armazenamento.'}}
function render(){if(!state.data)return;renderNav();const current=navItems.find(x=>x[0]===state.page);$('#crumbName').textContent=current?.[1]||'Minha agenda';$('#todayText').textContent=new Date(`${state.data.today}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});const views={dashboard:renderDashboard,calendar:renderCalendar,notebooklm:renderNotebookLM,exams:renderExams,content:renderContent,errors:renderErrors,qconcursos:renderQConcursos,settings:renderSettings};$('#page').innerHTML=(views[state.page]||renderCalendar)();if(state.page==='settings')loadStorageStatus()}
function renderNav(){const active=state.page;$('#navigation').innerHTML=navItems.map(([id,label,ic])=>`<button class="nav-link ${id===active?'active':''}" data-action="nav" data-page="${id}">${svg(ic)}<span>${label}</span></button>`).join('')}
function pageHead(kicker,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`}
function btn(label,action,kind='secondary',extra=''){return `<button class="button button-${kind}" data-action="${action}" ${extra}>${label}</button>`}
function dayWeek(dateStr){const d=toDate(dateStr);const monday=new Date(d);monday.setDate(d.getDate()-((d.getDay()+6)%7));return Array.from({length:7},(_,i)=>{const v=new Date(monday);v.setDate(monday.getDate()+i);return v})}
function fmtMinutes(m){const n=Number(m||0);const h=Math.floor(n/60),mm=n%60;return h?`${h}h${mm?` ${mm}min`:''}`:`${mm} min`}
function qFilterText(q,s){const parts=[`Disciplina: ${q.subject||subjectName(s.subject_id)}`,`Assunto: ${q.topic||s.topic||'não especificado'}`];if(q.bank)parts.push(`Banca: ${q.bank}`);if(q.institution)parts.push(`Órgão: ${q.institution}`);if(q.year_from||q.year_to)parts.push(`Ano: ${q.year_from||'qualquer'}–${q.year_to||'atual'}`);if(q.difficulty)parts.push(`Dificuldade: ${q.difficulty}`);if(q.mode)parts.push(`Tipo: ${q.mode}`);if(q.quantity)parts.push(`Quantidade: ${q.quantity} questões`);if(q.filter_notes)parts.push(`Observações: ${q.filter_notes}`);return parts.join('\n')}
function sessionCard(s){const q=s.qconcursos_filters||{};const completed=!!s.completed;return `<article class="study-card ${completed?'is-complete':''}"><div class="study-time">${s.start_time?`<strong>${esc(s.start_time)}</strong>`:'<strong class="time-flex">—</strong>'}<span>${fmtMinutes(s.minutes)}</span></div><div class="study-body"><div class="study-card-top"><div><div class="study-meta">${badge(activityLabel(s.activity_type),s.activity_type)}${s.exam_name?`<span class="study-exam">${esc(s.exam_name)} · ${esc(s.exam_cargo||'')}</span>`:''}</div><h3>${esc(subjectName(s.subject_id))}</h3></div>${completed?'<span class="done-mark">✓ Concluído</span>':btn('Concluir','complete-session','complete',`data-id="${s.id}"`)}${btn('Foco','focus-session','light',`data-id="${s.id}"`)}</div>${s.topic?`<p class="study-topic">${esc(s.topic)}</p>`:''}${s.objective?`<p class="study-objective">${esc(s.objective)}</p>`:''}${s.source_reference?`<p class="source-ref">Fonte: ${esc(s.source_reference)}</p>`:''}${q.enabled?`<div class="qc-task"><div><strong>Prática no QConcursos</strong><span>${q.quantity?`${q.quantity} questões sugeridas`:'Questões conforme os filtros abaixo'}</span></div><div class="qc-actions"><button class="button button-light button-sm" data-action="copy-qc-filters" data-id="${s.id}">Copiar filtros</button><a class="button button-qc button-sm" href="https://www.qconcursos.com/questoes-de-concursos/questoes" target="_blank" rel="noopener">Abrir QConcursos ↗</a></div></div>`:''}</div></article>`}
function badge(text,cls=''){return `<span class="badge ${esc(cls)}">${esc(text)}</span>`}
function metricCard(label,value,detail=''){return `<div class="metric-card"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(detail)}</small></div>`}
function renderDashboard(){const d=state.data.dashboard||{};const reviews=state.data.spaced_reviews||[];const errors=state.data.errors||[];return `<section>${pageHead('ACOMPANHAMENTO','Visão geral','Veja o que foi planejado, o que foi executado e onde você precisa concentrar esforço.',btn('Replanejar atrasos','replan','primary')+`<a class="button button-light" href="/api/export/study.csv">Exportar estudos ↗</a>`)}<div class="metrics-grid">${metricCard('Aderência',`${d.adherence_pct||0}%`,`${d.completed_sessions||0} de ${d.planned_sessions||0} sessões concluídas`)}${metricCard('Tempo realizado',fmtMinutes(d.actual_minutes||0),`de ${fmtMinutes(d.planned_minutes||0)} planejados`)}${metricCard('Questões',d.questions_done||0,`${d.accuracy_pct||0}% de acertos`)}${metricCard('Cobertura do edital',`${d.topic_coverage_pct||0}%`,`${d.topics_done||0} de ${d.topics_total||0} tópicos`)}${metricCard('Revisões atrasadas',d.overdue_reviews||0,'priorize sua memória')}${metricCard('Caderno de erros',d.open_errors||0,'itens em aberto')}</div><article class="card dashboard-card risk-card"><div class="card-section-heading"><div><div class="eyebrow">PRIORIZAÇÃO</div><h2>Matérias em risco</h2></div></div><div class="risk-grid">${(d.risk||[]).slice(0,6).map(r=>`<div class="risk-row"><div><strong>${esc(r.subject_name)}</strong><small>${r.accuracy_pct}% acertos · ${r.adherence_pct}% aderência</small></div><span class="badge ${r.level==='alto'?'warning':''}">${r.level}</span></div>`).join('')||'<p class="muted">Ainda não há dados suficientes.</p>'}</div></article><div class="dashboard-grid"><article class="card dashboard-card"><div class="card-section-heading"><div><div class="eyebrow">PRÓXIMAS REVISÕES</div><h2>Revisão espaçada</h2></div>${btn('Ver agenda','go-calendar','light')}</div>${reviews.slice(0,6).map(r=>`<div class="dashboard-row"><div><strong>${esc(r.topic||'Revisão de tópico')}</strong><small>${esc(r.subject_id)} · ${fmtDay(r.due)}</small></div><span class="badge ${r.due<state.data.today?'warning':''}">${r.due<state.data.today?'Atrasada':'Programada'}</span></div>`).join('')||'<p class="muted">Nenhuma revisão pendente.</p>'}</article><article class="card dashboard-card"><div class="card-section-heading"><div><div class="eyebrow">PONTOS DE ATENÇÃO</div><h2>Caderno de erros</h2></div>${btn('Abrir caderno','go-errors','light')}</div>${errors.slice(0,6).map(e=>`<div class="dashboard-row"><div><strong>${esc(e.topic||'Tópico não informado')}</strong><small>${esc(e.note)}</small></div><span class="badge">${esc(e.error_type)}</span></div>`).join('')||'<p class="muted">Nenhum erro aberto. Continue registrando suas dificuldades.</p>'}</article></div></section>`}
function newErrorModal(){const subjects=state.data.subjects.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');modal('Registrar erro',`<form id="newErrorForm"><div class="field"><label>Matéria</label><select name="subject_id" required>${subjects}</select></div><div class="field"><label>Tópico</label><input name="topic"></div><div class="field"><label>Tipo de erro</label><select name="error_type"><option>conteúdo</option><option>interpretação</option><option>desatenção</option><option>cálculo</option><option>memória</option><option>pegadinha</option><option>outro</option></select></div><div class="field"><label>O que aconteceu?</label><textarea name="note" required></textarea></div><div class="field"><label>Próxima revisão</label><input name="next_review" type="date"></div><div class="modal-actions"><button type="button" class="button button-light" data-action="close-modal">Cancelar</button><button type="submit" class="button button-primary">Salvar erro</button></div></form>`)}
function renderErrors(){const errors=state.data.errors||[];return `<section>${pageHead('DESEMPENHO','Caderno de erros','Registre por que errou e transforme suas dificuldades em revisões específicas.',btn('Registrar erro','new-error','primary')+btn('Replanejar atrasos','replan','secondary'))}<div class="notice notice-info">Erros de conteúdo e confiança baixa geram revisões mais próximas. O sistema não copia questões externas; registre apenas sua anotação e a referência.</div><div class="error-list">${errors.map(e=>`<article class="error-card"><div><span class="badge">${esc(e.error_type)}</span><h3>${esc(e.topic||'Tópico sem nome')}</h3><p>${esc(e.note)}</p><small>${esc(e.source||'Sem referência')} · próxima revisão ${fmtDay(e.next_review)}</small></div><button class="button button-light button-sm" data-action="resolve-error" data-id="${e.id}">Resolver</button></article>`).join('')||'<div class="empty-agenda"><h3>Seu caderno está limpo</h3><p>Ao registrar um erro durante uma sessão, ele aparecerá aqui para acompanhamento.</p></div>'}</div></section>`}
function focusModal(s){modal('Modo foco',`<div class="focus-session"><div class="eyebrow">${esc(s.activity_type||'ESTUDO')}</div><h2>${esc(s.subject_name||subjectName(s.subject_id))}</h2><p>${esc(s.topic||'Sem tópico específico')}</p><div class="focus-timer" id="focusTimer">00:00:00</div><div class="focus-actions"><button class="button button-primary" data-action="focus-start">Iniciar cronômetro</button><button class="button button-light" data-action="focus-log" data-id="${s.id}">Registrar resultado</button></div><small>${esc(s.objective||'Conclua o objetivo da sessão no seu ritmo.')}</small></div>`)}
function renderCalendar(){const selected=state.calendarDay||state.data.today;const sessions=state.data.sessions.filter(s=>s.day===selected).sort((a,b)=>(a.start_time||'99:99').localeCompare(b.start_time||'99:99')||a.id-b.id);const events=state.data.events.filter(e=>e.start_date<=selected&&e.end_date>=selected&&e.status!=='concluido');const week=dayWeek(selected);const total=sessions.reduce((a,s)=>a+Number(s.minutes||0),0);const done=sessions.filter(s=>s.completed).length;const dateLabel=fmtLong(selected);const isToday=selected===state.data.today;return `<section class="agenda-page">${pageHead('SEU DIA DE ESTUDOS',isToday?'Agenda de hoje':'Agenda do dia',dateLabel,btn('Importar planejamento','open-import','primary')+btn('+ Bloco manual','new-session','secondary'))}<div class="agenda-toolbar"><button class="icon-button" data-action="day-prev" aria-label="Semana anterior">‹</button><div class="week-strip">${week.map(d=>{const iso=isoDay(d),count=state.data.sessions.filter(s=>s.day===iso).length;return `<button class="week-day ${iso===selected?'selected':''} ${iso===state.data.today?'today':''}" data-action="select-day" data-date="${iso}"><span>${d.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}</span><strong>${d.getDate()}</strong><small>${count?`${count} ${count===1?'bloco':'blocos'}`:'—'}</small></button>`}).join('')}</div><button class="icon-button" data-action="day-next" aria-label="Próxima semana">›</button><button class="button button-light button-sm" data-action="go-today">Hoje</button><a class="button button-light button-sm" href="/api/calendar/export.ics">Exportar agenda ↗</a></div><div class="day-summary"><div><span class="summary-label">BLOCOS DO DIA</span><strong>${sessions.length}</strong></div><div><span class="summary-label">TEMPO PLANEJADO</span><strong>${fmtMinutes(total)}</strong></div><div><span class="summary-label">CONCLUÍDOS</span><strong>${done}/${sessions.length}</strong></div><div class="summary-progress"><div class="progress-line"><span style="width:${sessions.length?done/sessions.length*100:0}%"></span></div><small>${sessions.length?Math.round(done/sessions.length*100)+'% do dia concluído':'Seu planejamento aparece aqui'}</small></div></div>${events.length?`<div class="event-strip">${events.map(e=>`<div class="event-chip event-${esc(e.type)}"><span class="event-dot"></span><div><strong>${esc(e.title)}</strong><small>${eventLabel(e.type)}${e.start_date!==e.end_date?` · até ${fmtDay(e.end_date)}`:''}</small></div>${e.status!=='concluido'?`<button data-action="complete-event" data-id="${e.id}" title="Marcar como concluído">✓</button>`:badge('Concluído','success')}</div>`).join('')}</div>`:''}<div class="agenda-list-head"><div><div class="eyebrow">PLANO DO NOTEBOOKLM</div><h2>O que estudar</h2></div><span class="small-muted">${sessions.length?`${sessions.length} atividades programadas`:'Nenhuma atividade nesta data'}</span></div>${sessions.length?sessions.map(sessionCard).join(''):`<div class="empty-agenda"><div class="empty-icon">▦</div><h3>${isToday?'Sua agenda está livre por enquanto':'Nenhum estudo neste dia'}</h3><p>Envie os editais ao NotebookLM, peça o planejamento no formato EditalOS e importe o arquivo para preencher automaticamente sua agenda.</p>${btn('Ir para integração com NotebookLM','go-notebooklm','primary')}</div>`}<div class="agenda-footnote">O EditalOS organiza e acompanha seu plano. A análise dos editais e a elaboração do cronograma são feitas no NotebookLM.</div></section>`}
function renderNotebookLM(){const p=state.notebookPreview;return `<section class="notebook-page">${pageHead('INTEGRAÇÃO PRINCIPAL','Planejamento pelo NotebookLM','Você envia os editais ao NotebookLM. Ele prepara um arquivo estruturado; o EditalOS valida os dados e distribui as atividades no calendário.',btn('Abrir NotebookLM ↗','open-notebooklm','light'))}<div class="workflow-grid"><article class="workflow-card"><div class="workflow-number">01</div><div><h3>Adicione os editais ao NotebookLM</h3><p>Crie um notebook para sua preparação e carregue os editais, retificações, anexos e, se necessário, seu quadro semanal de disponibilidade.</p><a href="https://notebooklm.google.com/" target="_blank" rel="noopener" class="text-link">Abrir NotebookLM ↗</a></div></article><article class="workflow-card"><div class="workflow-number">02</div><div><h3>Use o prompt do EditalOS</h3><p>O prompt orienta a análise dos cargos, matérias, prazos e a criação de um cronograma diário com blocos de estudo e filtros para o QConcursos.</p><div class="inline-actions">${btn('Gerar prompt personalizado','load-prompt','secondary')}${btn('Copiar prompt','copy-prompt','light','id="copyPromptBtn" '+(state.notebookPrompt?'':'disabled'))}${btn('Baixar .TXT','download-prompt','light',''+(state.notebookPrompt?'':'disabled'))}</div></div></article><article class="workflow-card"><div class="workflow-number">03</div><div><h3>Baixe o arquivo JSON</h3><p>No NotebookLM, solicite um único arquivo <strong>editalos_plano.json</strong>. Caso a exportação estruturada não esteja disponível na sua conta, copie o JSON completo e salve como arquivo .json.</p><a href="/api/notebooklm/template" class="text-link">Baixar modelo de arquivo JSON ↓</a></div></article></div><div class="card prompt-card"><div class="card-section-heading"><div><div class="eyebrow">PROMPT PERSONALIZADO</div><h2>Instruções para o NotebookLM</h2><p>O texto considera as preferências atuais e os concursos já cadastrados nesta instalação.</p></div><span class="icon-bubble">✦</span></div><textarea id="notebookPrompt" readonly placeholder="Clique em ‘Gerar prompt personalizado’ para montar as instruções…">${esc(state.notebookPrompt)}</textarea></div><div class="import-panel"><div class="import-panel-head"><div><div class="eyebrow">IMPORTAR PLANEJAMENTO</div><h2>Trazer o cronograma para o calendário</h2><p>Formato recomendado: JSON. Também aceitamos TXT ou Markdown contendo somente o objeto JSON.</p></div><span class="file-icon">{ }</span></div><label class="file-drop" for="notebookPlanUpload"><input id="notebookPlanUpload" type="file" accept=".json,.txt,.md,application/json,text/plain,text/markdown"><span class="file-drop-icon">↑</span><strong>Selecionar arquivo do NotebookLM</strong><small>editalos_plano.json · até 8 MB</small></label>${p?renderNotebookPreview(p):''}</div></section>`}
function importPreferencesForm(p){const names=[];for(const e of (p.exams||[]))for(const sub of (e.subjects||[]))if(!names.includes(sub.name))names.push(sub.name);return `<div class="import-preferences"><div class="eyebrow">AJUSTE ANTES DE IMPORTAR</div><h3>Como distribuir este cronograma?</h3><p class="muted">Estas regras reorganizam datas e prioridades sem alterar o conteúdo do edital. A opção padrão preserva o JSON original.</p><div class="field-row"><div class="field"><label>Horas semanais</label><input id="importWeeklyHours" type="number" min="1" max="84" value="20"></div><div class="field"><label>Margem (%)</label><input id="importBufferPct" type="number" min="0" max="50" value="10"></div></div><div class="field-row"><div class="field"><label>Matérias por dia</label><input id="importSubjectsPerDay" type="number" min="1" max="7" value="2"></div><div class="field"><label>Modo</label><select id="importDistributionMode"><option value="preservar">Preservar datas do JSON</option><option value="balancear">Balancear matérias</option><option value="prioridade">Priorizar matérias selecionadas</option></select></div></div><div class="field"><label>Sequência</label><select id="importSequenceMode"><option value="intercalada">Intercalar matérias</option><option value="sequencial">Estudar em sequência por matéria</option></select></div><div class="field"><label>Matérias para aparecerem primeiro todos os dias possíveis</label><div class="preference-checks">${names.map(n=>`<label class="preference-check"><input type="checkbox" name="import_fixed_subjects" value="${esc(n)}"><span>${esc(n)}</span></label>`).join('')||'<span class="muted">Nenhuma matéria encontrada.</span>'}</div></div><div class="field"><label>Prioridade de distribuição (1 baixa · 5 máxima)</label><div class="preference-rows">${names.map(n=>`<div class="preference-row"><span>${esc(n)}</span><input class="import-priority" data-subject="${esc(n)}" type="number" min="1" max="5" value="3"></div>`).join('')}</div></div></div>`}
function readImportPreferences(){const priority={};document.querySelectorAll('.import-priority').forEach(x=>{if(Number(x.value)!==3)priority[x.dataset.subject]=Number(x.value)});return {weekly_hours:Number($('#importWeeklyHours')?.value||20),buffer_pct:Number($('#importBufferPct')?.value||10),subjects_per_day:Number($('#importSubjectsPerDay')?.value||2),distribution_mode:$('#importDistributionMode')?.value||'preservar',sequence_mode:$('#importSequenceMode')?.value||'intercalada',fixed_subjects:[...document.querySelectorAll('[name="import_fixed_subjects"]:checked')].map(x=>x.value),priority_overrides:priority}}
function renderNotebookPreview(p){const sm=p.summary||{};const deletes=Number(p.will_delete_sessions||0)+Number(p.will_delete_events||0);return `<div class="preview-panel"><div class="preview-title"><div><span class="eyebrow">PRÉ-IMPORTAÇÃO</span><h3>${esc(p.title)}</h3><small>${esc(p.filename)} · ${fmtDay(p.planning_period.start_date)} a ${fmtDay(p.planning_period.end_date)}</small></div>${badge('Aguardando aprovação','warning')}</div><div class="preview-kpis"><div><strong>${sm.exams||0}</strong><span>concursos/cargos</span></div><div><strong>${sm.subjects||0}</strong><span>disciplinas</span></div><div><strong>${sm.sessions||0}</strong><span>blocos de estudo</span></div><div><strong>${sm.events||0}</strong><span>prazos</span></div><div><strong>${fmtMinutes(sm.total_minutes||0)}</strong><span>carga total</span></div></div><div class="preview-exams">${(p.exams||[]).map(e=>`<div><strong>${esc(e.name)} — ${esc(e.cargo)}</strong><small>${(e.subjects||[]).map(s=>esc(s.name)).join(' · ')}</small></div>`).join('')}</div>${(p.warnings||[]).map(w=>`<div class="notice notice-warning">${esc(w)}</div>`).join('')}${deletes?`<div class="notice notice-danger"><strong>Esta substituição removerá ${Number(p.will_delete_sessions||0)} sessão(ões) pendente(s) e ${Number(p.will_delete_events||0)} prazo(s) de imports NotebookLM vinculados ao período.</strong><br> Sessões concluídas, manuais e imports fora do período serão preservados.</div>`:''}${p.existing_pending_sessions?`<div class="notice notice-info">Há ${p.existing_pending_sessions} blocos pendentes no período. Escolha se deseja acrescentar ou substituir os blocos anteriores do NotebookLM.</div>`:''}${importPreferencesForm(p)}<div class="field"><label for="notebookMode">Como importar</label><select id="notebookMode"><option value="append" ${state.notebookMode==='append'?'selected':''}>Acrescentar ao calendário — manter blocos existentes</option><option value="replace_notebooklm" ${state.notebookMode==='replace_notebooklm'?'selected':''}>Substituir blocos pendentes anteriores do NotebookLM no período</option></select><small>Blocos concluídos e sessões criadas manualmente não serão apagados na opção de substituição.</small></div><div class="preview-samples"><strong>Prévia de atividades</strong>${(p.sample_sessions||[]).slice(0,6).map(s=>`<div><span>${fmtDay(s.date)} ${s.start_time||''}</span><strong>${esc(s.subject)}</strong><small>${esc(s.topic||'') } · ${s.minutes} min</small></div>`).join('')}</div><div class="inline-actions"><button class="button button-primary" data-action="confirm-notebook-plan" data-token="${esc(p.token)}" ${deletes?'data-destructive="true"':''}>${deletes?'Confirmar substituição e colocar no calendário':'Confirmar e colocar no calendário'}</button><button class="button button-light" data-action="cancel-notebook-preview">Cancelar prévia</button></div></div>`}
function renderExams(){const exams=state.data.exams.filter(e=>e.active);return `<section>${pageHead('SEUS EDITAIS','Concursos em acompanhamento','Relação de cargos e disciplinas importados dos planejamentos do NotebookLM.',btn('Novo planejamento','go-notebooklm','primary'))}${exams.length?`<div class="exam-grid">${exams.map(e=>`<article class="exam-card"><div class="exam-card-top"><span class="eyebrow">${esc(e.banca||'BANCA NÃO INFORMADA')}</span>${badge(e.exam_date?`Prova ${fmtDay(e.exam_date)}`:'Prova não informada','')}</div><h3>${esc(e.name)}</h3><p>${esc(e.cargo)}</p><div class="subject-tags">${e.subjects.map(s=>`<span>${esc(s.name)}</span>`).join('')}</div><div class="exam-card-foot"><span>${e.subjects.length} disciplinas · prioridade ${e.priority===3?'alta':e.priority===2?'média':'baixa'}</span><button class="text-button" data-action="view-content" data-id="${e.id}">Ver conteúdo →</button></div></article>`).join('')}</div>`:`<div class="empty-agenda"><div class="empty-icon">▤</div><h3>Nenhum concurso cadastrado</h3><p>Importe o primeiro planejamento gerado pelo NotebookLM para cadastrar automaticamente os cargos e matérias.</p>${btn('Importar planejamento','open-import','primary')}</div>`}</section>`}
function renderContent(){const exams=state.data.exams;let exam=exams.find(e=>e.id===state.contentExamId)||exams[0];if(!exam)return `${pageHead('CONTEÚDO','Conteúdo programático','As matérias e os tópicos importados de seus editais aparecerão aqui.') }<div class="empty-agenda"><h3>Ainda não há conteúdo</h3><p>Importe seu planejamento NotebookLM.</p>${btn('Abrir integração','go-notebooklm','primary')}</div>`;state.contentExamId=exam.id;const progress=state.data.topic_progress||[];return `<section>${pageHead('CONTEÚDO PROGRAMÁTICO','Matérias e tópicos','Consulte o conteúdo importado e marque assuntos já estudados.',`<select id="contentExamSelect" class="select-inline">${exams.map(e=>`<option value="${e.id}" ${e.id===exam.id?'selected':''}>${esc(e.name)} · ${esc(e.cargo)}</option>`).join('')}</select>`)}<div class="content-grid">${exam.subjects.map(sub=>{const topics=sub.topics||[];const done=topics.filter(t=>progress.some(p=>p.exam_id===exam.id&&p.subject_id===sub.subject_id&&p.topic===t&&p.done)).length;return `<article class="content-card"><div class="content-card-head"><div><h3>${esc(sub.name)}</h3><small>Peso ${num(sub.weight)} · ${sub.questions?`${sub.questions} questões previstas`:'sem quantitativo'}</small></div>${badge(`${done}/${topics.length}`,'') }</div>${topics.length?topics.map(t=>{const checked=progress.some(p=>p.exam_id===exam.id&&p.subject_id===sub.subject_id&&p.topic===t&&p.done);return `<label class="topic-row"><input type="checkbox" data-topic-checkbox data-exam="${exam.id}" data-subject="${esc(sub.subject_id)}" data-topic="${esc(t)}" ${checked?'checked':''}><span>${esc(t)}</span></label>`}).join(''):'<p class="muted">Sem tópicos detalhados.</p>'}</article>`}).join('')}</div></section>`}
function renderQConcursos(){const count=state.data.sessions.filter(s=>s.qconcursos_filters?.enabled).length;return `<section>${pageHead('PLATAFORMA DE QUESTÕES','QConcursos','O EditalOS prepara a tarefa e os filtros. A resolução das questões acontece na sua conta do QConcursos.',`<a class="button button-qc" href="https://www.qconcursos.com/questoes-de-concursos/questoes" target="_blank" rel="noopener">Abrir banco de questões ↗</a>`)}<div class="qc-overview"><div class="qc-brand-mark">Q</div><div><div class="eyebrow">SUA ASSINATURA QCONCURSOS</div><h2>Planejamento aqui. Questões lá.</h2><p>O arquivo do NotebookLM pode programar blocos de questões e sugerir disciplina, assunto, banca, órgão, período, dificuldade e quantidade. Você aplica os filtros manualmente no QConcursos.</p><a href="https://www.qconcursos.com/questoes-de-concursos/questoes" target="_blank" rel="noopener" class="text-link">Acessar questões de concursos ↗</a></div></div><div class="qc-stats"><div><strong>${count}</strong><span>blocos com prática de questões no calendário</span></div><div><strong>${state.data.sessions.filter(s=>s.completed&&s.activity_type==='questoes').length}</strong><span>blocos de questões concluídos</span></div></div><div class="notice notice-info">A integração é intencionalmente externa: o EditalOS não coleta, copia ou automatiza o banco de questões. Isso evita armazenar conteúdo protegido e mantém a prática dentro da sua assinatura.</div><h2 class="section-title">Próximos blocos de questões</h2>${state.data.sessions.filter(s=>s.qconcursos_filters?.enabled).sort((a,b)=>a.day.localeCompare(b.day)).slice(0,12).map(s=>`<div class="qc-list-item"><div><strong>${fmtDay(s.day)} · ${esc(subjectName(s.subject_id))}</strong><small>${esc(s.topic||'Assunto não informado')} · ${s.qconcursos_filters.quantity||'—'} questões sugeridas</small></div><button class="button button-light button-sm" data-action="copy-qc-filters" data-id="${s.id}">Copiar filtros</button><a class="button button-qc button-sm" href="https://www.qconcursos.com/questoes-de-concursos/questoes" target="_blank" rel="noopener">Abrir ↗</a></div>`).join('')||'<p class="muted">Nenhum bloco de questões importado ainda. Inclua sessões do tipo “questoes” no planejamento do NotebookLM.</p>'}</section>`}
function renderSettings(){const s=state.data.settings,days=['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'];return `<section>${pageHead('PREFERÊNCIAS','Configurações de estudo','Essas informações são incluídas no prompt personalizado enviado ao NotebookLM.') }<form id="settingsForm" class="settings-card"><div class="field-row"><div class="field"><label>Disponibilidade semanal (horas)</label><input name="weekly_hours" type="number" min="1" max="84" value="${Number(s.weekly_hours||20)}" required></div><div class="field"><label>Margem para imprevistos (%)</label><input name="buffer_pct" type="number" min="0" max="50" value="${Number(s.buffer_pct??10)}" required></div></div><div class="field"><label>Dias preferenciais de estudo</label><div class="day-checks">${days.map((d,i)=>`<label><input type="checkbox" name="study_days" value="${i}" ${(s.study_days||[]).includes(i)?'checked':''}>${d}</label>`).join('')}</div></div><label class="checkbox-line"><input type="checkbox" name="auto_review" ${s.auto_review?'checked':''}> Incluir revisões espaçadas no prompt</label><div class="inline-actions"><button class="button button-primary" type="submit">Salvar preferências</button></div></form><div class="card storage-card"><div class="card-section-heading"><div><div class="eyebrow">PERSISTÊNCIA DOS DADOS</div><h2>Seus dados ficam salvos</h2><p id="storageStatusText">Verificando banco local...</p></div><span class="icon-bubble">▣</span></div><div class="inline-actions"><a class="button button-light" href="/api/export/backup.zip" download>Baixar backup completo (.zip)</a><button class="button button-light" data-action="restore-backup">Restaurar backup</button><input id="backupUpload" type="file" accept="application/json,.json,.zip,application/zip" hidden></div><small class="muted">O backup inclui progresso, editais, matérias, cronograma, sessões, revisões, erros, eventos, configurações e histórico de importações.</small></div><div class="card reset-card"><div class="eyebrow">ZONA DE PERIGO</div><h2>Limpar aplicação</h2><p>Apaga todo o progresso, cronograma, editais, sessões, revisões, erros, eventos, histórico e uploads. O catálogo básico de matérias será preservado.</p><button class="button button-danger" data-action="reset-app">Resetar tudo</button></div><div class="notice notice-info">O EditalOS salva automaticamente cada alteração no banco local. Faça backups periódicos para migrar ou recuperar seus dados. Em hospedagem serverless, configure armazenamento persistente antes de usar dados reais.</div></section>`}
function modal(title,content){state.modal=title;$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close-modal">×</button></div>${content}</div></div>`}
function closeModal(){state.modal=null;$('#modal-root').innerHTML=''}
function newSessionModal(){const examOptions=state.data.exams.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.cargo)}</option>`).join('');modal('Adicionar bloco de estudo',`<form id="newSessionForm"><div class="field"><label>Matéria *</label><select name="subject_id" required>${state.data.subjects.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Concurso (opcional)</label><select name="exam_id"><option value="">Sem vínculo</option>${examOptions}</select></div><div class="field-row"><div class="field"><label>Data</label><input type="date" name="day" value="${state.calendarDay||state.data.today}" required></div><div class="field"><label>Horário</label><input type="time" name="start_time" value="09:00"></div><div class="field"><label>Duração (min)</label><input type="number" name="minutes" value="50" min="5" max="720" required></div></div><div class="field"><label>Tópico</label><input name="topic" placeholder="Ex.: Atos administrativos"></div><div class="field"><label>Atividade</label><select name="activity_type"><option value="teoria">Teoria</option><option value="questoes">Questões</option><option value="revisao">Revisão</option><option value="lei_seca">Lei seca</option><option value="simulado">Simulado</option><option value="resumo">Resumo</option></select></div><div class="field"><label>Objetivo</label><input name="objective" placeholder="Ex.: resolver 20 questões e revisar erros"></div><label class="checkbox-line"><input type="checkbox" name="qc_enabled"> Direcionar sessão para o QConcursos</label><div class="field"><label>Quantidade de questões (se aplicável)</label><input name="qc_quantity" type="number" min="0" value="20"></div><div class="modal-actions"><button type="button" class="button button-light" data-action="close-modal">Cancelar</button><button type="submit" class="button button-primary">Salvar bloco</button></div></form>`)}
function newEventModal(){modal('Adicionar prazo',`<form id="newEventForm"><div class="field"><label>Descrição *</label><input name="title" required placeholder="Ex.: Encerramento das inscrições"></div><div class="field-row"><div class="field"><label>Tipo</label><select name="type">${[['inscricao','Inscrição'],['isencao','Isenção'],['pagamento','Pagamento'],['prova','Prova'],['recurso','Recurso'],['resultado','Resultado'],['outro','Outro']].map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></div><div class="field"><label>Concurso</label><select name="exam_id"><option value="">Sem vínculo</option>${state.data.exams.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.cargo)}</option>`).join('')}</select></div></div><div class="field-row"><div class="field"><label>Início</label><input type="date" name="start_date" value="${state.calendarDay||state.data.today}" required></div><div class="field"><label>Fim</label><input type="date" name="end_date" value="${state.calendarDay||state.data.today}" required></div></div><div class="modal-actions"><button type="button" class="button button-light" data-action="close-modal">Cancelar</button><button type="submit" class="button button-primary">Salvar prazo</button></div></form>`)}
function promptOptionsModal(){const days=['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'];const subjects=(state.data.subjects||[]).map(x=>`<label class="preference-check"><input type="checkbox" name="fixed_subjects" value="${esc(x.id)}"><span>${esc(x.name)}</span></label>`).join('');const priorities=(state.data.subjects||[]).map(x=>`<div class="preference-row"><span>${esc(x.name)}</span><select name="priority_subjects" data-subject-name="${esc(x.name)}"><option value="">Normal</option><option value="${esc(x.name)}">Prioritária</option></select></div>`).join('');modal('Montar prompt personalizado',`<form id="promptOptionsForm"><p class="modal-intro">Defina as regras que o NotebookLM deve seguir. Você poderá revisar o JSON e ajustar a distribuição novamente antes de importar.</p><div class="field-row"><div class="field"><label>Horas semanais</label><input name="weekly_hours" type="number" min="1" max="84" value="20" required></div><div class="field"><label>Margem para imprevistos (%)</label><input name="buffer_pct" type="number" min="0" max="50" value="10" required></div></div><div class="field"><label>Dias disponíveis</label><div class="day-checks">${days.map((x,i)=>`<label><input type="checkbox" name="study_days" value="${i}" ${i<6?'checked':''}>${x}</label>`).join('')}</div></div><div class="field-row"><div class="field"><label>Modo de distribuição</label><select name="distribution_mode"><option value="balanceada">Balanceada</option><option value="prioridade">Prioridade e prova próxima</option><option value="ciclo">Ciclo de matérias</option></select></div><div class="field"><label>Sequência</label><select name="sequence_mode"><option value="intercalada">Intercalada</option><option value="sequencial">Sequencial</option></select></div></div><div class="field-row"><div class="field"><label>Matérias por dia</label><input name="subjects_per_day" type="number" min="1" max="7" value="2"></div><div class="field"><label>Máximo por bloco (minutos)</label><input name="max_session_minutes" type="number" min="15" max="240" value="90"></div></div><div class="field"><label>Proporção do tempo</label><div class="ratio-grid"><label>Teoria <input name="theory_pct" type="number" min="0" max="100" value="45">%</label><label>Questões <input name="questions_pct" type="number" min="0" max="100" value="30">%</label><label>Revisão <input name="review_pct" type="number" min="0" max="100" value="25">%</label></div><small>A soma pode ser aproximada; o NotebookLM ajustará conforme edital e prova.</small></div><div class="field"><label>Matérias para contato diário</label><div class="preference-checks">${subjects||'<span class="muted">As matérias aparecerão após importar um plano.</span>'}</div></div><div class="field"><label>Prioridades específicas</label><div class="preference-rows">${priorities||'<span class="muted">Sem matérias cadastradas.</span>'}</div></div><div class="field"><label>Instruções adicionais</label><textarea name="custom_instructions" placeholder="Ex.: não estudar aos domingos; priorizar legislação seca; reservar sábado para simulado..."></textarea></div><label class="checkbox-line"><input type="checkbox" name="include_simulados" checked> Incluir simulados quando fizer sentido</label><div class="modal-actions"><button type="button" class="button button-light" data-action="close-modal">Cancelar</button><button type="submit" class="button button-primary">Gerar prompt</button></div></form>`)}
async function loadPrompt(){promptOptionsModal()}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copiado para a área de transferência.')}catch{const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();document.execCommand('copy');t.remove();toast('Copiado para a área de transferência.')}}
function downloadText(filename,text,type='text/plain'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url)}
async function uploadNotebookFile(file){state.notebookFileName=file.name;try{const fd=new FormData();fd.append('file',file);const p=await api('/api/notebooklm/preview',{method:'POST',body:fd});state.notebookPreview=p;state.notebookMode='append';render();toast('Arquivo validado. Revise o planejamento antes de importar.')}catch(e){toast(e.message,true)}}
async function action(type,el){try{switch(type){
 case 'nav':go(el.dataset.page);break;
 case 'menu':$('#sidebar').classList.toggle('open');break;
 case 'go-notebooklm':go('notebooklm');break;
 case 'open-import':{state.page='notebooklm';render();setTimeout(()=>$('#notebookPlanUpload')?.click(),0);break}
 case 'open-notebooklm':window.open('https://notebooklm.google.com/','_blank','noopener');break;
 case 'day-prev':{const d=toDate(state.calendarDay||state.data.today);d.setDate(d.getDate()-7);state.calendarDay=isoDay(d);render();break}
 case 'day-next':{const d=toDate(state.calendarDay||state.data.today);d.setDate(d.getDate()+7);state.calendarDay=isoDay(d);render();break}
 case 'go-today':state.calendarDay=state.data.today;render();break;
 case 'select-day':state.calendarDay=el.dataset.date;render();break;
 case 'complete-session':await patch(`/api/sessions/${el.dataset.id}`,{completed:true});await refresh();toast('Bloco concluído.');break;
 case 'go-calendar':go('calendar');break;
 case 'go-errors':go('errors');break;
 case 'new-error':newErrorModal();break;
 case 'replan':{const r=await post('/api/replan',{strategy:'distribuir'});await refresh();toast(r.moved?`${r.moved} bloco(s) atrasado(s) redistribuído(s).`:r.message);break}
 case 'focus-session':{const s=await api(`/api/sessions/${el.dataset.id}/focus`);focusSeconds=0;focusModal(s);break}
 case 'focus-start':{if(focusInterval)clearInterval(focusInterval);focusInterval=setInterval(()=>{focusSeconds++;const t=$('#focusTimer');if(t){const h=Math.floor(focusSeconds/3600),m=Math.floor(focusSeconds%3600/60),s=focusSeconds%60;t.textContent=[h,m,s].map(x=>String(x).padStart(2,'0')).join(':')}},1000);toast('Cronômetro iniciado.');break}
 case 'focus-log':{const minutes=Number(window.prompt('Quantos minutos você estudou?',String(Math.max(1,Math.round(focusSeconds/60)))))||0;const questions=Number(window.prompt('Quantas questões resolveu?','0'))||0;const correct=Number(window.prompt('Quantos acertos?','0'))||0;const note=window.prompt('Observação da sessão (opcional):','')||'';await post('/api/study-logs',{session_id:Number(el.dataset.id),actual_minutes:minutes,questions_done:questions,questions_correct:correct,difficulty:'adequada',confidence:3,interruptions:0,notes:note});if(focusInterval)clearInterval(focusInterval);closeModal();await refresh();toast('Execução registrada e próxima revisão criada.');break}
 case 'resolve-error':await patch(`/api/errors/${el.dataset.id}`,{status:'resolvido'});await refresh();toast('Erro marcado como resolvido.');break;
 case 'complete-event':await patch(`/api/events/${el.dataset.id}`,{status:'concluido'});await refresh();toast('Prazo marcado como concluído.');break;
 case 'new-session':newSessionModal();break;
 case 'new-event':newEventModal();break;
 case 'close-modal':closeModal();break;
 case 'modal-backdrop':if(el.classList.contains('modal-backdrop'))closeModal();break;
 case 'load-prompt':await loadPrompt();break;
 case 'copy-prompt':if(!state.notebookPrompt)throw new Error('Gere o prompt personalizado primeiro.');await copyText(state.notebookPrompt);break;
 case 'download-prompt':if(!state.notebookPrompt)throw new Error('Gere o prompt personalizado primeiro.');downloadText('PROMPT_NOTEBOOKLM_EDITALOS.txt',state.notebookPrompt);break;
 case 'restore-backup':$('#backupUpload')?.click();break;
 case 'reset-app':{const phrase=window.prompt('Esta ação apagará todos os dados. Digite RESETAR TUDO para confirmar:');if(phrase!=='RESETAR TUDO')break;const result=await post('/api/storage/reset',{confirmation:phrase});state.notebookPreview=null;state.notebookPrompt='';state.page='calendar';await refresh();toast(result.message||'Aplicação resetada.');break}
 case 'confirm-notebook-plan':{if(!state.notebookPreview)break;const mode=$('#notebookMode')?.value||state.notebookMode;const deletions=Number(state.notebookPreview.will_delete_sessions||0)+Number(state.notebookPreview.will_delete_events||0);if(mode==='replace_notebooklm'&&deletions&&!window.confirm(`A substituição removerá ${state.notebookPreview.will_delete_sessions||0} sessão(ões) e ${state.notebookPreview.will_delete_events||0} prazo(s) pendente(s) do NotebookLM. Continuar?`))break;const result=await post('/api/notebooklm/confirm',{token:el.dataset.token,mode,preferences:readImportPreferences()});state.notebookPreview=null;state.calendarDay=result.first_session_date||state.data.today;state.page='calendar';await refresh();toast(`${result.exams} concurso(s), ${result.sessions} blocos e ${result.events} prazos adicionados ao calendário.`);break}
 case 'cancel-notebook-preview':state.notebookPreview=null;render();break;
 case 'copy-qc-filters':{const s=state.data.sessions.find(x=>x.id===Number(el.dataset.id));if(!s)break;await copyText(qFilterText(s.qconcursos_filters||{},s));break}
 case 'view-content':state.contentExamId=Number(el.dataset.id);go('content');break;
 case 'export-ics':window.location.href='/api/calendar/export.ics';break;
 }}catch(e){toast(e.message,true)}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const actionName=el.dataset.action;if(el.tagName==='A'&&el.target==='_blank')return;e.preventDefault();action(actionName,el)});
document.addEventListener('change',async e=>{
 if(e.target.id==='notebookPlanUpload'){const f=e.target.files?.[0];if(f)await uploadNotebookFile(f);e.target.value='';return}
 if(e.target.id==='backupUpload'){const f=e.target.files?.[0];if(f){if(!window.confirm('Restaurar este backup substituirá os dados atuais. Continuar?')){e.target.value='';return}try{const fd=new FormData();fd.append('file',f);const r=await fetch('/api/import/backup.json',{method:'POST',body:fd});const b=await r.json();if(!r.ok)throw new Error(b.detail||'Falha ao restaurar backup.');state.notebookPreview=null;await refresh();toast(b.message||'Backup restaurado.')}catch(err){toast(err.message,true)}}e.target.value='';return}
 if(e.target.id==='notebookMode'){state.notebookMode=e.target.value;return}
 if(e.target.id==='contentExamSelect'){state.contentExamId=Number(e.target.value);render();return}
 if(e.target.matches('[data-topic-checkbox]')){try{await post('/api/topics/progress',{exam_id:Number(e.target.dataset.exam),subject_id:e.target.dataset.subject,topic:e.target.dataset.topic,done:e.target.checked});await refresh()}catch(err){toast(err.message,true)}return}
});
document.addEventListener('submit',async e=>{const f=e.target;if(!['promptOptionsForm','newSessionForm','newEventForm','settingsForm','newErrorForm'].includes(f.id))return;e.preventDefault();const d=new FormData(f),get=k=>String(d.get(k)||'').trim();try{
 if(f.id==='promptOptionsForm'){const priorities=[...f.querySelectorAll('[name="priority_subjects"]')].map(x=>x.value).filter(Boolean);const options={weekly_hours:Number(get('weekly_hours')),buffer_pct:Number(get('buffer_pct')),study_days:d.getAll('study_days').map(Number),strategy:'equilibrado',distribution_mode:get('distribution_mode'),sequence_mode:get('sequence_mode'),subjects_per_day:Number(get('subjects_per_day')),fixed_subjects:d.getAll('fixed_subjects'),priority_subjects:priorities,theory_pct:Number(get('theory_pct')),questions_pct:Number(get('questions_pct')),review_pct:Number(get('review_pct')),include_simulados:!!d.get('include_simulados'),max_session_minutes:Number(get('max_session_minutes')),custom_instructions:get('custom_instructions')};const r=await fetch('/api/notebooklm/prompt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(options)});if(!r.ok){const b=await r.json();throw new Error(b.detail||'Não foi possível gerar o prompt.')}state.notebookPrompt=await r.text();closeModal();render();toast('Prompt personalizado gerado com suas preferências.');}
 if(f.id==='newSessionForm'){const qc=!!d.get('qc_enabled');await post('/api/sessions',{day:get('day'),subject_id:get('subject_id'),minutes:Number(get('minutes')),completed:false,exam_id:get('exam_id')?Number(get('exam_id')):null,start_time:get('start_time'),topic:get('topic'),activity_type:get('activity_type'),objective:get('objective'),qconcursos_filters:{enabled:qc,subject:subjectName(get('subject_id')),topic:get('topic'),quantity:Number(get('qc_quantity')||0)},source_reference:''});state.calendarDay=get('day');closeModal();await refresh();toast('Bloco adicionado à agenda.');}
 if(f.id==='newEventForm'){await post('/api/events',{title:get('title'),type:get('type'),exam_id:get('exam_id')?Number(get('exam_id')):null,start_date:get('start_date'),end_date:get('end_date')});state.calendarDay=get('start_date');closeModal();await refresh();toast('Prazo adicionado ao calendário.');}
 if(f.id==='settingsForm'){const settings={weekly_hours:Number(get('weekly_hours')),buffer_pct:Number(get('buffer_pct')),strategy:'equilibrado',study_days:d.getAll('study_days').map(Number),auto_review:!!d.get('auto_review')};await post('/api/settings',settings);await refresh();toast('Preferências salvas. O próximo prompt usará esses dados.');}
 if(f.id==='newErrorForm'){await post('/api/errors',{subject_id:get('subject_id'),topic:get('topic'),error_type:get('error_type'),note:get('note'),next_review:get('next_review')||null});closeModal();await refresh();toast('Erro registrado no caderno.');}
 }catch(err){toast(err.message,true)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
refresh();
